// IAMServiceHandler is an implementation of the rpc.v1.IAMService service.
type IAMServiceHandler interface {
	// ExchangeToken: Exchange SSO provider token for internal JWT
	// - Verifies Google/Apple JWKS signature
	// - Creates user if not exists (find-or-create)
	// - Links SSO identity
	// - Issues internal JWT
	// Public endpoint (no authentication required)
	ExchangeToken(context.Context, *connect.Request[v1.ExchangeTokenRequest]) (*connect.Response[v1.ExchangeTokenResponse], error)
	// Login: Authenticate with email and password
	// - Verifies email exists
	// - Checks bcrypt password hash
	// - Returns internal JWT
	// Public endpoint (no authentication required)
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	// ChangePassword: Update password for authenticated user
	// - Verifies current password
	// - Hashes new password
	// - Invalidates all sessions
	// Requires authentication
	ChangePassword(context.Context, *connect.Request[v1.ChangePasswordRequest]) (*connect.Response[v1.ChangePasswordResponse], error)
	// RequestPasswordReset: Initiate password reset flow
	// - Sends reset email with token
	// - Does NOT reveal if email exists (security)
	// Public endpoint (no authentication required)
	RequestPasswordReset(context.Context, *connect.Request[v1.RequestPasswordResetRequest]) (*connect.Response[v1.RequestPasswordResetResponse], error)
	// ResetPassword: Complete password reset with token
	// - Verifies reset token validity
	// - Updates password
	// - Invalidates all sessions
	// Public endpoint (no authentication required)
	ResetPassword(context.Context, *connect.Request[v1.ResetPasswordRequest]) (*connect.Response[v1.ResetPasswordResponse], error)
	// Logout: Invalidate current session
	// - Marks session as invalidated
	// - Token remains valid until expiry (stateless JWT)
	// Requires authentication
	Logout(context.Context, *connect.Request[v1.LogoutRequest]) (*connect.Response[v1.LogoutResponse], error)
	// LogoutAllSessions: Invalidate all user sessions
	// - Used for security incidents
	// - Marks all sessions as invalidated
	// Requires authentication
	LogoutAllSessions(context.Context, *connect.Request[v1.LogoutAllSessionsRequest]) (*connect.Response[v1.LogoutAllSessionsResponse], error)
	// GetActiveSessions: List user's active sessions
	// - Shows last activity, IP, user agent
	// - Allows selective session termination
	// Requires authentication
	GetActiveSessions(context.Context, *connect.Request[v1.GetActiveSessionsRequest]) (*connect.Response[v1.GetActiveSessionsResponse], error)
	// GetProfile: Get current user profile
	// - Returns user info + SSO identities
	// Requires authentication
	GetProfile(context.Context, *connect.Request[v1.GetProfileRequest]) (*connect.Response[v1.GetProfileResponse], error)
	// UpdateProfile: Update user profile
	// - Display name, profile picture
	// Requires authentication
	UpdateProfile(context.Context, *connect.Request[v1.UpdateProfileRequest]) (*connect.Response[v1.UpdateProfileResponse], error)
	// LinkSSOIdentity: Link additional SSO provider to account
	// - Verifies SSO token
	// - Creates sso_identity record
	// Requires authentication
	LinkSSOIdentity(context.Context, *connect.Request[v1.LinkSSOIdentityRequest]) (*connect.Response[v1.LinkSSOIdentityResponse], error)
	// UnlinkSSOIdentity: Remove SSO provider link
	// - Must have password or another SSO provider
	// - Deletes sso_identity record
	// Requires authentication
	UnlinkSSOIdentity(context.Context, *connect.Request[v1.UnlinkSSOIdentityRequest]) (*connect.Response[v1.UnlinkSSOIdentityResponse], error)
	// GetUserOrganizations: List organizations user belongs to
	// - Returns org info + user's role
	// Requires authentication
	GetUserOrganizations(context.Context, *connect.Request[v1.GetUserOrganizationsRequest]) (*connect.Response[v1.GetUserOrganizationsResponse], error)
	// SwitchOrganization: Change active organization context
	// - Issues new JWT with organization_id
	// - Used for multi-tenant context switching
	// Requires authentication
	SwitchOrganization(context.Context, *connect.Request[v1.SwitchOrganizationRequest]) (*connect.Response[v1.SwitchOrganizationResponse], error)
	// InviteUser: Send invitation to join organization
	// - Creates invitation record
	// - Sends invitation email
	// Requires: admin or owner role in organization
	InviteUser(context.Context, *connect.Request[v1.InviteUserRequest]) (*connect.Response[v1.InviteUserResponse], error)
	// CancelInvitation: Cancel pending invitation
	// Requires: admin or owner role in organization
	CancelInvitation(context.Context, *connect.Request[v1.CancelInvitationRequest]) (*connect.Response[v1.CancelInvitationResponse], error)
	// ListInvitations: List pending invitations for organization
	// Requires: admin or owner role in organization
	ListInvitations(context.Context, *connect.Request[v1.ListInvitationsRequest]) (*connect.Response[v1.ListInvitationsResponse], error)
	// AcceptInvitation: Accept invitation and join organization
	// - Creates organization_membership
	// - Marks invitation as accepted
	// - If new user: creates account with provided SSO or password
	// Public endpoint (creates account if needed)
	AcceptInvitation(context.Context, *connect.Request[v1.AcceptInvitationRequest]) (*connect.Response[v1.AcceptInvitationResponse], error)
	// ListEmployees: List organization employees with pagination, sorting, and optional email filter
	// Returns employees from organization.employee table
	// Requires: any authenticated organization member
	ListEmployees(context.Context, *connect.Request[v1.ListEmployeesRequest]) (*connect.Response[v1.ListEmployeesResponse], error)
	// GetEmployeeCards: Fetch lightweight display data for a batch of employees by ID.
	// Returns name, email, department, and presence status for rendering UserCard components.
	// Designed for frontend UI resolution — use instead of exposing full employee records.
	// Accepts up to 100 employee IDs per request.
	// Requires: any authenticated organization member
	GetEmployeeCards(context.Context, *connect.Request[v1.GetEmployeeCardsRequest]) (*connect.Response[v1.GetEmployeeCardsResponse], error)
	// PreviewEmployeeImport: Validate and preview a list of employees before import.
	// Returns each employee with a willBeImported flag (false if duplicate email detected).
	// Requires: ADMIN or OWNER
	PreviewEmployeeImport(context.Context, *connect.Request[v1.PreviewEmployeeImportRequest]) (*connect.Response[v1.PreviewEmployeeImportResponse], error)
	// ExecuteEmployeeImport: Bulk-create organization.employee records and send invitation emails.
	// Only employees with willBeImported=true should be submitted.
	// Requires: ADMIN or OWNER
	ExecuteEmployeeImport(context.Context, *connect.Request[v1.ExecuteEmployeeImportRequest]) (*connect.Response[v1.ExecuteEmployeeImportResponse], error)
	// ListPermissions: Returns all system-defined permissions grouped by domain.
	// Reads from public.permission reference table (global data).
	ListPermissions(context.Context, *connect.Request[v1.ListPermissionsRequest]) (*connect.Response[v1.ListPermissionsResponse], error)
	// CreateRole: Create a custom role with selected permissions.
	CreateRole(context.Context, *connect.Request[v1.CreateRoleRequest]) (*connect.Response[v1.CreateRoleResponse], error)
	// UpdateRole: Modify a role's name, description, or permissions.
	// Cannot remove lockout-prevention permissions from the Owner system role.
	UpdateRole(context.Context, *connect.Request[v1.UpdateRoleRequest]) (*connect.Response[v1.UpdateRoleResponse], error)
	// DeleteRole: Delete a custom role (system roles cannot be deleted).
	// Cascades: removes all employee assignments and permission mappings.
	DeleteRole(context.Context, *connect.Request[v1.DeleteRoleRequest]) (*connect.Response[v1.DeleteRoleResponse], error)
	// ListRoles: List all roles for the organization (system + custom).
	ListRoles(context.Context, *connect.Request[v1.ListRolesRequest]) (*connect.Response[v1.ListRolesResponse], error)
	// GetRole: Get a single role with its permissions.
	GetRole(context.Context, *connect.Request[v1.GetRoleRequest]) (*connect.Response[v1.GetRoleResponse], error)
	// AssignRole: Assign a role to an employee.
	AssignRole(context.Context, *connect.Request[v1.AssignRoleRequest]) (*connect.Response[v1.AssignRoleResponse], error)
	// RevokeRole: Remove a role from an employee.
	RevokeRole(context.Context, *connect.Request[v1.RevokeRoleRequest]) (*connect.Response[v1.RevokeRoleResponse], error)
	// ListEmployeeRoles: List all roles assigned to a specific employee.
	ListEmployeeRoles(context.Context, *connect.Request[v1.ListEmployeeRolesRequest]) (*connect.Response[v1.ListEmployeeRolesResponse], error)
	// GetEmployeePermissions: Returns the effective permission set for an employee.
	// Computes the union of permissions from all assigned roles.
	GetEmployeePermissions(context.Context, *connect.Request[v1.GetEmployeePermissionsRequest]) (*connect.Response[v1.GetEmployeePermissionsResponse], error)
	// LoginWithPIN authenticates a worker using org-scoped login_identifier + PIN.
	// Resolves organization from subdomain, then looks up identity by login_identifier.
	LoginWithPIN(context.Context, *connect.Request[v1.LoginWithPINRequest]) (*connect.Response[v1.LoginWithPINResponse], error)
	// SetPIN sets or changes a worker's PIN credential.
	// Required after first login with a temporary PIN (pin_change_required=true).
	// Can be called with a pin_change_token (no auth header) or with a valid JWT.
	SetPIN(context.Context, *connect.Request[v1.SetPINRequest]) (*connect.Response[v1.SetPINResponse], error)
	// CreateOrgAccount creates a single org-managed worker account.
	// Returns the generated temporary PIN (visible once).
	CreateOrgAccount(context.Context, *connect.Request[v1.CreateOrgAccountRequest]) (*connect.Response[v1.CreateOrgAccountResponse], error)
	// BatchCreateOrgAccounts creates multiple org-managed worker accounts.
	// Returns results with one-time PIN list.
	BatchCreateOrgAccounts(context.Context, *connect.Request[v1.BatchCreateOrgAccountsRequest]) (*connect.Response[v1.BatchCreateOrgAccountsResponse], error)
	// DeactivateOrgAccount deactivates an org-managed worker account.
	// Immediately invalidates all active sessions.
	DeactivateOrgAccount(context.Context, *connect.Request[v1.DeactivateOrgAccountRequest]) (*connect.Response[v1.DeactivateOrgAccountResponse], error)
	// UnlockOrgAccount unlocks an org-managed account locked due to failed PIN attempts.
	// Optionally generates a new temporary PIN.
	UnlockOrgAccount(context.Context, *connect.Request[v1.UnlockOrgAccountRequest]) (*connect.Response[v1.UnlockOrgAccountResponse], error)
	// ResetOrgAccountCredential resets credentials for an org-managed account.
	// Generates a new temporary PIN and revokes existing PIN credentials.
	ResetOrgAccountCredential(context.Context, *connect.Request[v1.ResetOrgAccountCredentialRequest]) (*connect.Response[v1.ResetOrgAccountCredentialResponse], error)
	// ListOrgAccounts lists org-managed worker accounts with status info.
	ListOrgAccounts(context.Context, *connect.Request[v1.ListOrgAccountsRequest]) (*connect.Response[v1.ListOrgAccountsResponse], error)
}

